// Client-side Heuristic Analysis Engine
// Used for high-fidelity demonstration and fallback when the FastAPI backend is offline.
// All results generated by this engine are explicitly flagged with isDemo = true.

import { getRiskClassification } from './helpers';

export const analyzePhishingLocally = (message) => {
  const text = (message || '').toLowerCase();
  let score = 15; // base baseline
  const indicators = [];
  const reasons = [];

  // Urgency check
  const urgencyKeywords = ['immediately', 'urgent', 'blocked', 'suspended', '24 hours', 'within 2 hours', 'today itself', 'terminated', 'action required'];
  const matchedUrgency = urgencyKeywords.filter(k => text.includes(k));
  if (matchedUrgency.length > 0) {
    score += 25;
    indicators.push({
      name: "High Urgency Coercion",
      severity: "high",
      desc: `Detected pressure tactics demanding prompt compliance: "${matchedUrgency.join(', ')}"`
    });
    reasons.push("Urgent psychological coercion is commonly used in phishing to prevent victims from verifying claims.");
  }

  // Financial / Credential harvesting
  const finKeywords = ['kyc', 'pan card', 'bank account', 'yono', 'otp', 'credit card', 'debit card', 'pin', 'refund', 'lottery', 'winner', 'cashback', 'electricity bill', 'power cut'];
  const matchedFin = finKeywords.filter(k => text.includes(k));
  if (matchedFin.length > 0) {
    score += 30;
    indicators.push({
      name: "Sensitive Identity & Financial Request",
      severity: "critical",
      desc: `Solicts sensitive financial data or payment actions: "${matchedFin.join(', ')}"`
    });
    reasons.push("Legitimate institutions never request sensitive credentials, PAN updates, or passwords via unverified SMS or messages.");
  }

  // Links & URLs
  const linkMatches = text.match(/(https?:\/\/[^\s]+|bit\.ly[^\s]*|tinyurl[^\s]*|is\.gd[^\s]*|t\.co[^\s]*|[a-z0-9\-]+\.(xyz|top|vip|club|tk|ml)[^\s]*)/gi);
  if (linkMatches) {
    score += 30;
    indicators.push({
      name: "Suspicious or Obfuscated Link Detected",
      severity: "critical",
      desc: `Message embeds non-standard destination: ${linkMatches[0]}`
    });
    reasons.push("Presence of shortened or unverified URLs is the primary delivery mechanism for credential harvesting landing pages.");
  }

  // Cap score
  score = Math.min(Math.max(score, 8), 98);
  const classification = getRiskClassification(score);

  return {
    id: `sim-phish-${Date.now().toString(36)}`,
    type: 'phishing',
    category: 'Phishing Message',
    inputSnippet: message,
    timestamp: new Date().toISOString(),
    riskScore: score,
    riskClassification: classification,
    summary: score > 50
      ? "Elevated threat indicators detected. The content exhibits strong linguistic and structural patterns characteristic of social engineering smishing attacks."
      : "Low probability of malicious intent detected. Message does not display typical phishing patterns or credential-stealing hooks.",
    indicators: indicators.length > 0 ? indicators : [
      { name: "Clean Communication Pattern", severity: "low", desc: "No known phishing trigger keywords or obfuscated URLs identified." }
    ],
    reasons: reasons.length > 0 ? reasons : [
      "No urgency triggers or sensitive credential demands found in the provided text."
    ],
    recommendations: score > 50 ? [
      "Do NOT click any link or reply with OTP, passwords, or personal identity numbers.",
      "Block the sender and verify account status directly using official apps or hotlines.",
      "Report the incident to the National Cyber Crime Portal at 1930."
    ] : [
      "Even though risk is low, remain alert and never share passwords or OTPs over text."
    ],
    isDemo: true
  };
};

export const analyzeUrlLocally = (urlInput) => {
  let cleanUrl = (urlInput || '').trim();
  if (!cleanUrl.startsWith('http://') && !cleanUrl.startsWith('https://')) {
    cleanUrl = `https://${cleanUrl}`;
  }

  let hostname = '';
  try {
    const parsed = new URL(cleanUrl);
    hostname = parsed.hostname.toLowerCase();
  } catch {
    hostname = cleanUrl.toLowerCase();
  }

  // Verified safe list
  const safeDomains = ['google.com', 'microsoft.com', 'apple.com', 'amazon.in', 'github.com', 'gov.in', 'nic.in', 'sbi.co.in', 'hdfcbank.com', 'icicibank.com', 'wikipedia.org'];
  const isKnownSafe = safeDomains.some(d => hostname === d || hostname.endsWith(`.${d}`));

  if (isKnownSafe) {
    return {
      id: `sim-url-${Date.now().toString(36)}`,
      type: 'url',
      category: 'Malicious URL',
      inputSnippet: cleanUrl,
      timestamp: new Date().toISOString(),
      riskScore: 5,
      riskClassification: 'LOW',
      summary: "Verified authentic corporate or institutional domain with established identity authority and spotless safety record.",
      indicators: [
        { name: "Recognized Authority Domain", severity: "low", desc: `Hostname (${hostname}) matches verified authoritative security whitelist.` },
        { name: "Clean Reputation Telemetry", severity: "low", desc: "No malicious payloads, fraud records, or phishing reports registered." }
      ],
      reasons: [
        "Hostname belongs to a verified enterprise or government authority.",
        "Valid domain registration history and secure DNS records."
      ],
      recommendations: [
        "The destination is safe for regular browsing.",
        "Always check the browser address bar padlock for transport security."
      ],
      isDemo: true
    };
  }

  let score = 20;
  const indicators = [];
  const reasons = [];

  // Suspicious TLD
  const suspiciousTLDs = ['.xyz', '.top', '.vip', '.club', '.gq', '.tk', '.ml', '.work', '.click', '.buzz'];
  if (suspiciousTLDs.some(tld => hostname.endsWith(tld))) {
    score += 35;
    indicators.push({
      name: "High-Risk Top-Level Domain (TLD)",
      severity: "high",
      desc: `The URL uses a top-level domain frequently associated with throwaway scam sites.`
    });
    reasons.push("Fraudsters frequently leverage low-cost, minimal-vetting TLDs for disposable phishing infrastructure.");
  }

  // Brand spoofing / typosquatting
  const targetBrands = ['sbi', 'paytm', 'hdfc', 'icici', 'axis', 'netflix', 'amazon', 'flipkart', 'google', 'paypal', 'apple', 'challan'];
  const matchedBrand = targetBrands.find(b => hostname.includes(b) && !hostname.endsWith(`${b}.com`) && !hostname.endsWith(`${b}.in`) && !hostname.endsWith(`${b}.co.in`));
  if (matchedBrand) {
    score += 40;
    indicators.push({
      name: `Brand Typosquatting / Spoofing (${matchedBrand.toUpperCase()})`,
      severity: "critical",
      desc: `Domain contains trademarked brand keyword '${matchedBrand}' within an unauthorized third-party namespace.`
    });
    reasons.push(`The domain appears engineered to deceive customers of ${matchedBrand.toUpperCase()} into believing it is an official portal.`);
  }

  // IP address as host
  if (/^(\d{1,3}\.){3}\d{1,3}$/.test(hostname)) {
    score += 30;
    indicators.push({
      name: "Raw IP Address Hostname",
      severity: "high",
      desc: "URL points directly to an IP address instead of a registered domain name."
    });
    reasons.push("Legitimate consumer-facing portals operate under registered brand domains, not raw numeric IP endpoints.");
  }

  // Hyphenation / Subdomain stuffing
  if ((hostname.match(/-/g) || []).length >= 2 || (hostname.match(/\./g) || []).length >= 3) {
    score += 15;
    indicators.push({
      name: "Excessive Hyphenation & Subdomain Stacking",
      severity: "medium",
      desc: "Subdomain structure exhibits evasive naming conventions often used to mask malicious origins."
    });
    reasons.push("Multiple hyphens and excessive nested subdomains are often deployed to imitate legit paths on mobile viewports.");
  }

  score = Math.min(Math.max(score, 12), 96);
  const classification = getRiskClassification(score);

  return {
    id: `sim-url-${Date.now().toString(36)}`,
    type: 'url',
    category: 'Malicious URL',
    inputSnippet: cleanUrl,
    timestamp: new Date().toISOString(),
    riskScore: score,
    riskClassification: classification,
    summary: score > 50 
      ? `High-risk indicators identified for ${hostname}. Site exhibits strong characteristics of typosquatting or fraudulent credential harvesting.`
      : `Moderate or low risk detected for ${hostname}. No overt critical blacklisting indicators discovered, but exercise standard caution.`,
    indicators: indicators.length > 0 ? indicators : [
      { name: "Standard Web Endpoint", severity: "low", desc: "No known brand spoofing or suspicious domain anomalies flagged." }
    ],
    reasons: reasons.length > 0 ? reasons : [
      "The domain structure appears standard without typical deceptive markers."
    ],
    recommendations: score > 50 ? [
      "Do NOT enter passwords, credit cards, or UPI PINs on this website.",
      "Exit the site immediately and close the browser tab.",
      "Submit this URL to Google Safe Browsing and CERT-In."
    ] : [
      "Verify the SSL certificate before submitting any sensitive details."
    ],
    isDemo: true
  };
};

export const analyzeDigitalArrestLocally = (content) => {
  const text = (content || '').toLowerCase();
  let score = 25;
  const indicators = [];
  const reasons = [];

  // Digital arrest terminology
  const arrestKeywords = ['digital arrest', 'virtual arrest', 'digital detention', 'video interrogation', 'skype call', 'stay on camera'];
  const matchedArrest = arrestKeywords.filter(k => text.includes(k));
  if (matchedArrest.length > 0) {
    score += 45;
    indicators.push({
      name: "Explicit 'Digital Arrest' Coercion Pattern",
      severity: "critical",
      desc: `Detected fraudulent concept of digital confinement: "${matchedArrest.join(', ')}"`
    });
    reasons.push("Indian law and penal code contain NO provision for 'digital arrest' or video-call interrogations.");
  }

  // Agency impersonation
  const agencyKeywords = ['cbi', 'customs', 'narcotics', 'ed', 'enforcement directorate', 'supreme court', 'police commissioner', 'trai', 'mumbai police', 'delhi police'];
  const matchedAgency = agencyKeywords.filter(k => text.includes(k));
  if (matchedAgency.length > 0) {
    score += 35;
    indicators.push({
      name: "Law Enforcement / Intelligence Agency Impersonation",
      severity: "critical",
      desc: `Invokes official authority to intimidate: "${matchedAgency.map(a => a.toUpperCase()).join(', ')}"`
    });
    reasons.push("Federal enforcement bodies (CBI/ED/Customs) never issue arrest warrants or conduct official inquiries via video calls.");
  }

  // Narcotics / Illegal parcel narrative
  const parcelKeywords = ['courier', 'fedex', 'dhl', 'parcel', 'drugs', 'mdma', 'contraband', 'passport', 'aadhaar linked to crime'];
  const matchedParcel = parcelKeywords.filter(k => text.includes(k));
  if (matchedParcel.length > 0) {
    score += 25;
    indicators.push({
      name: "Illegal Parcel / Narcotics Seizure Script",
      severity: "high",
      desc: `Classic social engineering narrative: "${matchedParcel.join(', ')}"`
    });
    reasons.push("Fabricating intercepted courier packages is the standard opener for extortion rings.");
  }

  // Financial extortion / escrow
  const escrowKeywords = ['escrow', 'verification account', 'rbi account', 'security deposit', 'transfer funds', 'clearance fund', 'freeze account'];
  const matchedEscrow = escrowKeywords.filter(k => text.includes(k));
  if (matchedEscrow.length > 0) {
    score += 30;
    indicators.push({
      name: "Fund Transfer / Bogus Escrow Demand",
      severity: "critical",
      desc: `Demands monetary transfer under the guise of legal clearance: "${matchedEscrow.join(', ')}"`
    });
    reasons.push("No government agency demands financial transfers into 'safe clearance accounts' during criminal investigations.");
  }

  score = Math.min(Math.max(score, 15), 99);
  const classification = getRiskClassification(score);

  return {
    id: `sim-arrest-${Date.now().toString(36)}`,
    type: 'digital-arrest',
    category: 'Digital Arrest Scam',
    inputSnippet: content,
    timestamp: new Date().toISOString(),
    riskScore: score,
    riskClassification: classification,
    summary: score > 60
      ? "CRITICAL FRAUD ALERT: High-probability Digital Arrest extortion detected. The caller/sender is attempting psychological isolation and financial extortion."
      : "Low indication of digital arrest extortion, but continue to exercise vigilance if approached by unsolicited callers.",
    indicators: indicators.length > 0 ? indicators : [
      { name: "Standard Text Content", severity: "low", desc: "No legal intimidation or digital arrest keywords detected." }
    ],
    reasons: reasons.length > 0 ? reasons : [
      "Content does not exhibit characteristics of simulated virtual confinement."
    ],
    recommendations: score > 60 ? [
      "DISCONNECT IMMEDIATELY. You cannot be arrested over a phone or video call.",
      "Do NOT transfer any money or disclose your bank balance.",
      "Call the National Cyber Crime Helpline at 1930 immediately.",
      "File a formal report on https://cybercrime.gov.in."
    ] : [
      "Never share Aadhaar numbers or personal documents with unverified callers."
    ],
    isDemo: true
  };
};

export const analyzeApplicationLocally = (file) => {
  const fileName = (file?.name || 'app-sample.apk').toLowerCase();
  const fileSize = file?.size || 15 * 1024 * 1024;
  let score = 30;
  const indicators = [];
  const reasons = [];

  // Dangerous keyword detection in APK name
  const riskyKeywords = ['loan', 'instant', 'cash', 'credit', 'hack', 'mod', 'free', 'crack', 'spy', 'track', 'bonus'];
  const matchedKeywords = riskyKeywords.filter(k => fileName.includes(k));
  if (matchedKeywords.length > 0) {
    score += 40;
    indicators.push({
      name: "High-Risk Application Nomenclature",
      severity: "high",
      desc: `Package name contains high-risk predatory keywords: "${matchedKeywords.join(', ')}"`
    });
    reasons.push("Predatory loan apps and spyware frequently disguise themselves as instant credit utilities or modded applications.");
  }

  // Sideloaded package risk
  indicators.push({
    name: "Off-Market Sideload Distribution",
    severity: "medium",
    desc: "Unpackaged APK distributed outside Google Play Store lacking verified developer identity."
  });
  reasons.push("Sideloaded apps bypass Google Play Protect gatekeeping and automated malware scanning.");

  // File size anomaly heuristics
  if (fileSize < 2 * 1024 * 1024) {
    score += 20;
    indicators.push({
      name: "Suspiciously Small Package Size (<2MB)",
      severity: "medium",
      desc: "Micro-sized APK commonly acts as a lightweight downloader / dropper to fetch secondary payloads."
    });
    reasons.push("Micro-droppers bypass basic static scans by fetching malicious payloads after installation.");
  } else if (fileSize > 80 * 1024 * 1024) {
    score += 15;
    indicators.push({
      name: "Bloated / Packed APK",
      severity: "low",
      desc: "Large binary size often indicates bundled native libraries or resource obfuscation."
    });
  } else {
    score += 15;
  }

  // Simulated static permission risks for demo
  indicators.push({
    name: "Invasive Permissions Flagged (Simulated)",
    severity: "critical",
    desc: "Static manifest analysis indicates potential requests for READ_SMS, READ_CONTACTS, and ACCESS_FINE_LOCATION."
  });
  reasons.push("Invasive permissions allow unauthorized harvesting of private phonebooks and interception of banking 2FA OTPs.");

  score = Math.min(Math.max(score, 25), 92);
  const classification = getRiskClassification(score);

  return {
    id: `sim-apk-${Date.now().toString(36)}`,
    type: 'application',
    category: 'Application Safety',
    inputSnippet: `${file?.name || 'app-sample.apk'} (${(fileSize / (1024 * 1024)).toFixed(1)} MB)`,
    timestamp: new Date().toISOString(),
    riskScore: score,
    riskClassification: classification,
    summary: "Static analysis detected elevated risks associated with off-market Android sideloading and potential predatory permission profiles.",
    indicators,
    reasons,
    recommendations: [
      "DO NOT install this APK on any personal or banking device.",
      "If installed, enable Airplane Mode and remove the app immediately via Android Safe Mode.",
      "Only install banking and financial utilities verified by RBI directly from the Google Play Store."
    ],
    isDemo: true
  };
};
